$ErrorActionPreference='Stop'
$compiler=Join-Path $env:WINDIR 'Microsoft.NET\Framework64\v4.0.30319\csc.exe'
$files=Get-ChildItem -LiteralPath (Join-Path $PSScriptRoot 'Source') -Filter '*.cs' | ForEach-Object FullName
& $compiler /nologo /target:winexe /platform:x64 /optimize+ /utf8output ('/out:'+(Join-Path $PSScriptRoot 'Jago-Companion.exe')) ('/win32manifest:'+(Join-Path $PSScriptRoot 'Source\app.manifest')) ('/win32icon:'+(Join-Path $PSScriptRoot 'Brand\Companion.ico')) /reference:System.dll /reference:System.Core.dll /reference:System.Drawing.dll /reference:System.Windows.Forms.dll /reference:System.Web.Extensions.dll /reference:System.Web.dll /reference:System.IO.Compression.dll /reference:System.IO.Compression.FileSystem.dll ('/resource:'+(Join-Path $PSScriptRoot 'Source\ImageTextEngine.ps1')+',ImageTextEngine.ps1') $files
if($LASTEXITCODE -ne 0){throw 'Companion build failed'}

& $compiler /nologo /target:winexe /platform:x64 /optimize+ ('/out:'+(Join-Path $PSScriptRoot 'Jago-Capture.exe')) ('/win32icon:'+(Join-Path $PSScriptRoot 'Brand\Capture.ico')) /reference:System.dll /reference:System.Core.dll /reference:System.Drawing.dll /reference:System.Web.Extensions.dll /reference:System.Xaml.dll /reference:System.Windows.Forms.dll ('/reference:'+(Join-Path $env:WINDIR 'Microsoft.NET\Framework64\v4.0.30319\WPF\PresentationFramework.dll')) ('/reference:'+(Join-Path $env:WINDIR 'Microsoft.NET\Framework64\v4.0.30319\WPF\PresentationCore.dll')) ('/reference:'+(Join-Path $env:WINDIR 'Microsoft.NET\Framework64\v4.0.30319\WPF\WindowsBase.dll')) (Join-Path $PSScriptRoot 'CaptureLauncher.cs') (Join-Path $PSScriptRoot 'ShellTasks.cs') /reference:System.Core.dll (Join-Path $PSScriptRoot 'Source\ThemeWidgets.cs') (Join-Path $PSScriptRoot 'Source\ThemeColors.cs') (Join-Path $PSScriptRoot 'Source\ScrollTheme.cs')
if($LASTEXITCODE -ne 0){throw 'Capture launcher build failed'}

$recordingLibrary=Join-Path $PSScriptRoot 'Dependencies\ScreenRecorderLib\ScreenRecorderLib.dll'
& $compiler /nologo /target:winexe /platform:x64 /optimize+ /utf8output ('/out:'+(Join-Path $PSScriptRoot 'Jago-Recorder.exe')) ('/win32manifest:'+(Join-Path $PSScriptRoot 'Source\app.manifest')) ('/win32icon:'+(Join-Path $PSScriptRoot 'Brand\Capture.ico')) ('/reference:'+$recordingLibrary) /reference:System.dll /reference:System.Core.dll /reference:System.Drawing.dll /reference:System.Windows.Forms.dll (Join-Path $PSScriptRoot 'Recorder.cs') (Join-Path $PSScriptRoot 'RecordingInk.cs') (Join-Path $PSScriptRoot 'Source\ThemeWidgets.cs') (Join-Path $PSScriptRoot 'Source\ThemeColors.cs') (Join-Path $PSScriptRoot 'Source\ScrollTheme.cs') (Join-Path $PSScriptRoot 'Source\LiveWindows.cs')
if($LASTEXITCODE -ne 0){throw 'Recorder build failed'}
Copy-Item -LiteralPath $recordingLibrary -Destination (Join-Path $PSScriptRoot 'ScreenRecorderLib.dll') -Force

& $compiler /nologo /target:winexe /platform:x64 /optimize+ /utf8output ('/out:'+(Join-Path $PSScriptRoot 'Jago-Update.exe')) ('/win32icon:'+(Join-Path $PSScriptRoot 'Brand\Companion.ico')) /reference:System.dll /reference:System.Core.dll /reference:System.Drawing.dll /reference:System.Windows.Forms.dll (Join-Path $PSScriptRoot 'UpdateAssist.cs') (Join-Path $PSScriptRoot 'Source\UpdateProtocol.cs')
if($LASTEXITCODE -ne 0){throw 'Update assistant build failed'}

$webPreview=Join-Path $PSScriptRoot 'Dependencies\WebView2'
Copy-Item -LiteralPath (Join-Path $webPreview 'lib\net462\Microsoft.Web.WebView2.Core.dll') -Destination $PSScriptRoot -Force
Copy-Item -LiteralPath (Join-Path $webPreview 'lib\net462\Microsoft.Web.WebView2.WinForms.dll') -Destination $PSScriptRoot -Force
Copy-Item -LiteralPath (Join-Path $webPreview 'runtimes\win-x64\native\WebView2Loader.dll') -Destination $PSScriptRoot -Force
$wpf=Join-Path $env:WINDIR 'Microsoft.NET\Framework64\v4.0.30319\WPF'
& $compiler /nologo /target:winexe /platform:x64 /optimize+ /utf8output ('/out:'+(Join-Path $PSScriptRoot 'Jago-Preview.exe')) ('/win32manifest:'+(Join-Path $PSScriptRoot 'Source\app.manifest')) ('/win32icon:'+(Join-Path $PSScriptRoot 'Brand\Capture.ico')) /reference:System.dll /reference:System.Core.dll /reference:System.Drawing.dll /reference:System.Windows.Forms.dll /reference:System.Xaml.dll ('/reference:'+(Join-Path $wpf 'PresentationFramework.dll')) ('/reference:'+(Join-Path $wpf 'PresentationCore.dll')) ('/reference:'+(Join-Path $wpf 'WindowsBase.dll')) ('/reference:'+(Join-Path $wpf 'WindowsFormsIntegration.dll')) (Join-Path $PSScriptRoot 'VideoPreview.cs') (Join-Path $PSScriptRoot 'PreviewSeeking.cs') (Join-Path $PSScriptRoot 'QuickFilePreview.cs') (Join-Path $PSScriptRoot 'QuickDocumentPreview.cs') /reference:System.Web.dll /reference:System.Web.Extensions.dll ('/reference:'+(Join-Path $PSScriptRoot 'Microsoft.Web.WebView2.Core.dll')) ('/reference:'+(Join-Path $PSScriptRoot 'Microsoft.Web.WebView2.WinForms.dll')) (Join-Path $PSScriptRoot 'Source\ThemeWidgets.cs') (Join-Path $PSScriptRoot 'Source\ThemeColors.cs') (Join-Path $PSScriptRoot 'Source\ScrollTheme.cs')
if($LASTEXITCODE -ne 0){throw 'Video preview build failed'}
